+use crate::geometry::Point;
+
+#[derive(Clone, Debug)]
+struct Node {
+    index: u32,
+    point: Point,
+    prev: usize,
+    next: usize,
+    steiner: bool,
+}
+
+#[derive(Default)]
+struct Triangulator {
+    nodes: Vec<Node>,
+}
+
+impl Triangulator {
+    fn insert_node(&mut self, index: u32, point: Point, last: Option<usize>) -> usize {
+        let node_index = self.nodes.len();
+        self.nodes.push(Node {
+            index,
+            point,
+            prev: node_index,
+            next: node_index,
+            steiner: false,
+        });
+
+        if let Some(last_index) = last {
+            let next_index = self.nodes[last_index].next;
+            self.nodes[node_index].prev = last_index;
+            self.nodes[node_index].next = next_index;
+            self.nodes[last_index].next = node_index;
+            self.nodes[next_index].prev = node_index;
+        }
+
+        node_index
+    }
+
+    fn remove_node(&mut self, node_index: usize) {
+        let prev = self.nodes[node_index].prev;
+        let next = self.nodes[node_index].next;
+        self.nodes[prev].next = next;
+        self.nodes[next].prev = prev;
+    }
+
+    fn linked_list(&mut self, ring: &[Point], clockwise: bool) -> Option<usize> {
+        if ring.is_empty() {
+            return None;
+        }
+
+        let mut last = None;
+        if clockwise == (signed_area(ring) > 0.0) {
+            for (index, point) in ring.iter().copied().enumerate() {
+                last = Some(self.insert_node(index as u32, point, last));
+            }
+        } else {
+            for (index, point) in ring.iter().copied().enumerate().rev() {
+                last = Some(self.insert_node(index as u32, point, last));
+            }
+        }
+
+        if let Some(last_index) = last {
+            let next_index = self.nodes[last_index].next;
+            if self.equals(last_index, next_index) {
+                self.remove_node(last_index);
+                return Some(next_index);
+            }
+        }
+
+        last
+    }
+
+    fn equals(&self, a: usize, b: usize) -> bool {
+        self.nodes[a].point == self.nodes[b].point
+    }
+
+    fn area(&self, a: usize, b: usize, c: usize) -> f64 {
+        area(self.nodes[a].point, self.nodes[b].point, self.nodes[c].point)
+    }
+
+    fn filter_points(&mut self, start: usize, end: Option<usize>) -> Option<usize> {
+        let mut end = end.unwrap_or(start);
+        let mut current = start;
+
+        loop {
+            let mut again = false;
+            let next = self.nodes[current].next;
+            let prev = self.nodes[current].prev;
+
+            if !self.nodes[current].steiner
+                && (self.equals(current, next) || self.area(prev, current, next) == 0.0)
+            {
+                self.remove_node(current);
+                current = prev;
+                end = prev;
+                if self.nodes[current].next == current {
+                    return None;
+                }
+                again = true;
+            } else {
+                current = next;
+            }
+
+            if !(again || current != end) {
+                break;
+            }
+        }
+
+        Some(end)
+    }
+
+    fn is_ear(&self, ear: usize) -> bool {
+        let prev = self.nodes[ear].prev;
+        let next = self.nodes[ear].next;
+
+        if self.area(prev, ear, next) >= 0.0 {
+            return false;
+        }
+
+        let a = self.nodes[prev].point;
+        let b = self.nodes[ear].point;
+        let c = self.nodes[next].point;
+        let mut probe = self.nodes[next].next;
+
+        while probe != prev {
+            let p = self.nodes[probe].point;
+            if point_in_triangle(a, b, c, p)
+                && self.area(self.nodes[probe].prev, probe, self.nodes[probe].next) >= 0.0
+            {
+                return false;
+            }
+            probe = self.nodes[probe].next;
+        }
+
+        true
+    }
+
+    fn earcut_linked(&mut self, start: usize, triangles: &mut Vec<u32>, pass: u8) {
+        let mut ear = start;
+        let mut stop = start;
+
+        while self.nodes[ear].prev != self.nodes[ear].next {
+            let prev = self.nodes[ear].prev;
+            let next = self.nodes[ear].next;
+
+            if self.is_ear(ear) {
+                triangles.push(self.nodes[prev].index);
+                triangles.push(self.nodes[ear].index);
+                triangles.push(self.nodes[next].index);
+
+                self.remove_node(ear);
+                ear = self.nodes[next].next;
+                stop = self.nodes[next].next;
+                continue;
+            }
+
+            ear = next;
+
+            if ear == stop {
+                if pass == 0 {
+                    if let Some(filtered) = self.filter_points(ear, None) {
+                        self.earcut_linked(filtered, triangles, 1);
+                    }
+                }
+                return;
+            }
+        }
+    }
+}
+
+pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
+    if polygon.is_empty() || polygon[0].len() < 3 {
+        return Vec::new();
+    }
+
+    let mut triangulator = Triangulator::default();
+    let Some(outer) = triangulator.linked_list(&polygon[0], true) else {
+        return Vec::new();
+    };
+    let Some(outer) = triangulator.filter_points(outer, None) else {
+        return Vec::new();
+    };
+
+    let mut triangles = Vec::new();
+    triangulator.earcut_linked(outer, &mut triangles, 0);
+    triangles
+}
+
+fn signed_area(ring: &[Point]) -> f64 {
+    let mut sum = 0.0;
+    let mut prev = ring[ring.len() - 1];
+
+    for &point in ring {
+        sum += (prev.x - point.x) * (point.y + prev.y);
+        prev = point;
+    }
+
+    sum
+}
+
+fn area(a: Point, b: Point, c: Point) -> f64 {
+    (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
+}
+
+fn point_in_triangle(a: Point, b: Point, c: Point, p: Point) -> bool {
+    (c.x - p.x) * (a.y - p.y) >= (a.x - p.x) * (c.y - p.y)
+        && (a.x - p.x) * (b.y - p.y) >= (b.x - p.x) * (a.y - p.y)
+        && (b.x - p.x) * (c.y - p.y) >= (c.x - p.x) * (b.y - p.y)
+}
