pub mod atoi;
pub mod earcut;
pub mod geometry;

use geometry::Point;

pub fn build_polygon(n: i32) -> Vec<Vec<Point>> {
    let mut polygon = Vec::with_capacity(1);
    let mut fractal = Vec::new();
    let total = n.saturating_mul(2);

    if total > 0 {
        for i in 0..total {
            let t = f64::from(i) / f64::from(total);
            let x = t * 3.0;
            let y = (t * 10.0).sin() * (-t).exp() * 2.0 + 1.0;
            fractal.push(Point::new(x, y));
        }
    }

    fractal.push(Point::new(3.0, 0.0));
    fractal.push(Point::new(0.0, 0.0));
    polygon.push(fractal);
    polygon
}

pub fn generate_indices(n: i32) -> Vec<u32> {
    let polygon = build_polygon(n);
    earcut::earcut(&polygon)
}

pub fn format_indices(indices: &[u32]) -> String {
    let mut output = String::new();
    for index in indices {
        output.push_str(&index.to_string());
        output.push(' ');
    }
    output
}

#[cfg(test)]
mod tests {
    use super::{format_indices, generate_indices};
    use crate::atoi::cpp_atoi;

    #[test]
    fn matches_sample_outputs() {
        assert_eq!(format_indices(&generate_indices(1)), "1 0 3 ");
        assert_eq!(format_indices(&generate_indices(2)), "1 0 5 5 4 3 2 1 5 ");
        assert_eq!(
            format_indices(&generate_indices(5)),
            "1 0 11 10 9 8 8 7 6 3 2 1 1 11 10 10 8 6 4 3 1 10 6 5 "
        );
        assert_eq!(
            format_indices(&generate_indices(10)),
            "1 0 21 20 19 18 18 17 16 16 15 14 14 13 12 6 5 4 4 3 2 2 1 21 20 18 16 16 14 12 7 6 4 4 2 21 20 16 12 7 4 21 20 12 11 8 7 21 21 20 11 9 8 21 "
        );
        assert_eq!(
            format_indices(&generate_indices(15)),
            "1 0 31 30 29 28 28 27 26 26 25 24 24 23 22 22 21 20 20 19 18 9 8 7 7 6 5 5 4 3 3 2 1 30 28 26 26 24 22 22 20 18 10 9 7 7 5 3 3 1 31 30 26 22 22 18 17 10 7 3 30 22 17 11 10 3 30 17 16 12 11 3 3 31 30 30 16 15 30 15 14 "
        );
        assert_eq!(
            format_indices(&generate_indices(19)),
            "1 0 39 38 37 36 36 35 34 34 33 32 32 31 30 30 29 28 28 27 26 26 25 24 12 11 10 10 9 8 8 7 6 6 5 4 4 3 2 2 1 39 38 36 34 34 32 30 30 28 26 26 24 23 12 10 8 8 6 4 4 2 39 38 34 30 30 26 23 13 12 8 8 4 39 38 30 23 13 8 39 38 23 22 14 13 39 38 22 21 15 14 39 39 38 21 16 15 39 17 16 39 "
        );
    }

    #[test]
    fn cpp_atoi_matches_common_cases() {
        assert_eq!(cpp_atoi("19"), 19);
        assert_eq!(cpp_atoi("-7"), -7);
        assert_eq!(cpp_atoi("+12xyz"), 12);
        assert_eq!(cpp_atoi("abc"), 0);
    }
